SELECT "t3"."order_number", "t3"."invoice_id", "t3"."due", "t3"."open_amount", 'hold_ar' AS "route", 'overdue' AS "context"
FROM (SELECT "order_number", "invoice_id", "due", "amount" - "paid" AS "open_amount"
        FROM (SELECT "t0"."order_number", "t0"."customer", "t0"."channel", "t0"."fulfilling_warehouse", "t0"."value", "t0"."placed_date", "t0"."state", "invoice"."invoice_id", "invoice"."order_number" AS "order_number0", "invoice"."issued", "invoice"."due", "invoice"."amount", "invoice"."paid", "invoice"."status"
                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                        FROM "order"
                        WHERE "state" IN ('held', 'placed')) AS "t0"
                    INNER JOIN "invoice" ON "t0"."customer" = "invoice"."customer") AS "t1"
        WHERE "t1"."status" = 'open' AND "t1"."due" < :as_of) AS "t3"
    INNER JOIN (SELECT "order_number"
        FROM (SELECT "t31"."order_number", "t31"."customer", "t31"."channel", "t31"."fulfilling_warehouse", "t31"."value", "t31"."placed_date", "t31"."state", COALESCE("t31"."n_short", 0) AS "n_short", COALESCE("t31"."n_price", 0) AS "n_price", COALESCE("t37"."n_due", 0) AS "n_due"
                FROM (SELECT "t19"."order_number", "t19"."customer", "t19"."channel", "t19"."fulfilling_warehouse", "t19"."value", "t19"."placed_date", "t19"."state", "t19"."n_short", "t30"."n_price"
                        FROM (SELECT "t5"."order_number", "t5"."customer", "t5"."channel", "t5"."fulfilling_warehouse", "t5"."value", "t5"."placed_date", "t5"."state", "t18"."n_short"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t5"
                                    LEFT JOIN (SELECT "order_number", COUNT("line_no") AS "n_short"
                                        FROM (SELECT "t13"."order_number", "t13"."customer", "t13"."channel", "t13"."fulfilling_warehouse", "t13"."value", "t13"."placed_date", "t13"."state", "t13"."line_no", "t13"."item", "t13"."quantity", "t13"."unit_price", "t13"."ext_sales_price", "t13"."warehouse", "t13"."sold_date", "t13"."customer0", "t13"."channel0", "t13"."as_of_date", "t13"."quantity_on_hand", "t13"."_ttrp_g_n8_0", "t13"."_ttrp_g_n8_1", "t14"."warehouse" AS "warehouse0", "t14"."from_date", "t14"."to_date", "t14"."reason", COALESCE("t13"."quantity_on_hand", 0) AS "on_hand", "t14"."warehouse" IS NOT NULL AS "outage"
                                                FROM (SELECT "t8"."order_number", "t8"."customer", "t8"."channel", "t8"."fulfilling_warehouse", "t8"."value", "t8"."placed_date", "t8"."state", "t8"."line_no", "t8"."item", "t8"."quantity", "t8"."unit_price", "t8"."ext_sales_price", "t8"."warehouse", "t8"."sold_date", "t8"."customer0", "t8"."channel0", "t12"."as_of_date", "t12"."quantity_on_hand", "t12"."_ttrp_g_n8_0", "t12"."_ttrp_g_n8_1"
                                                        FROM (SELECT "t7"."order_number", "t7"."customer", "t7"."channel", "t7"."fulfilling_warehouse", "t7"."value", "t7"."placed_date", "t7"."state", "sales_line"."line_no", "sales_line"."item", "sales_line"."quantity", "sales_line"."unit_price", "sales_line"."ext_sales_price", "sales_line"."warehouse", "sales_line"."sold_date", "sales_line"."customer" AS "customer0", "sales_line"."channel" AS "channel0"
                                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                        FROM "order"
                                                                        WHERE "state" IN ('held', 'placed')) AS "t7"
                                                                    INNER JOIN "sales_line" ON "t7"."order_number" = "sales_line"."order_number") AS "t8"
                                                            LEFT JOIN (SELECT "t9"."as_of_date", "t9"."item", "t9"."warehouse", "t9"."quantity_on_hand", "t9"."_ttrp_g_n8_0", "t9"."_ttrp_g_n8_1"
                                                                FROM (SELECT "as_of_date", "item", "warehouse", "quantity_on_hand", CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1"
                                                                        FROM "inventory") AS "t9"
                                                                    INNER JOIN (SELECT CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END AS "_ttrp_g_n8_0", CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END AS "_ttrp_g_n8_1", MAX("as_of_date") AS "_ttrp_latest_n8"
                                                                        FROM "inventory"
                                                                        GROUP BY CASE WHEN "item" IS NULL THEN 'n' ELSE 'v' || CAST("item" AS VARCHAR) END, CASE WHEN "warehouse" IS NULL THEN 'n' ELSE 'v' || CAST("warehouse" AS VARCHAR) END) AS "t11" ON "t9"."_ttrp_g_n8_0" = "t11"."_ttrp_g_n8_0" AND "t9"."_ttrp_g_n8_1" = "t11"."_ttrp_g_n8_1" AND "t9"."as_of_date" = "t11"."_ttrp_latest_n8") AS "t12" ON "t8"."item" = "t12"."item" AND "t8"."warehouse" = "t12"."warehouse") AS "t13"
                                                    LEFT JOIN (SELECT *
                                                        FROM "warehouse_outage"
                                                        WHERE "from_date" <= :as_of AND "to_date" >= :as_of) AS "t14" ON "t13"."warehouse" = "t14"."warehouse") AS "t15"
                                        WHERE "t15"."outage" OR "t15"."on_hand" < "t15"."quantity"
                                        GROUP BY "order_number") AS "t18" ON "t5"."order_number" = "t18"."order_number") AS "t19"
                            LEFT JOIN (SELECT "order_number0" AS "order_number", COUNT("line_no0") AS "n_price"
                                FROM (SELECT "t22"."order_number", "t22"."line_no", "t22"."item", "t22"."unit_price", "t22"."customer", "t22"."channel", "t22"."placed_date", "t26"."order_number" AS "order_number0", "t26"."line_no" AS "line_no0", "t26"."price"
                                        FROM (SELECT "sales_line0"."order_number", "sales_line0"."line_no", "sales_line0"."item", "sales_line0"."unit_price", "t21"."customer", "t21"."channel", "t21"."placed_date"
                                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                        FROM "order"
                                                        WHERE "state" IN ('held', 'placed')) AS "t21"
                                                    INNER JOIN "sales_line" AS "sales_line0" ON "t21"."order_number" = "sales_line0"."order_number") AS "t22"
                                            INNER JOIN (SELECT "t25"."order_number", "t25"."line_no", COALESCE("customer_price"."price", "price_list"."price") AS "price"
                                                FROM (SELECT "sales_line1"."order_number", "sales_line1"."line_no", "sales_line1"."item", "sales_line1"."unit_price", "t24"."customer", "t24"."channel", "t24"."placed_date"
                                                        FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                                                FROM "order"
                                                                WHERE "state" IN ('held', 'placed')) AS "t24"
                                                            INNER JOIN "sales_line" AS "sales_line1" ON "t24"."order_number" = "sales_line1"."order_number") AS "t25"
                                                    LEFT JOIN "customer_price" ON "t25"."item" = "customer_price"."item" AND "t25"."customer" = "customer_price"."customer" AND "t25"."placed_date" >= "customer_price"."valid_from" AND ("customer_price"."valid_to" IS NULL OR "t25"."placed_date" <= "customer_price"."valid_to")
                                                    LEFT JOIN "price_list" ON "t25"."item" = "price_list"."item" AND "t25"."channel" = "price_list"."channel" AND "t25"."placed_date" >= "price_list"."valid_from" AND ("price_list"."valid_to" IS NULL OR "t25"."placed_date" <= "price_list"."valid_to")) AS "t26" ON "t22"."order_number" = "t26"."order_number" AND "t22"."line_no" = "t26"."line_no") AS "t27"
                                WHERE "t27"."price" IS NULL OR ABS("t27"."unit_price" - "t27"."price") > :tolerance
                                GROUP BY "order_number0") AS "t30" ON "t19"."order_number" = "t30"."order_number") AS "t31"
                    LEFT JOIN (SELECT "order_number", COUNT("invoice_id") AS "n_due"
                        FROM (SELECT "t33"."order_number", "t33"."customer", "t33"."channel", "t33"."fulfilling_warehouse", "t33"."value", "t33"."placed_date", "t33"."state", "invoice0"."invoice_id", "invoice0"."order_number" AS "order_number0", "invoice0"."issued", "invoice0"."due", "invoice0"."amount", "invoice0"."paid", "invoice0"."status"
                                FROM (SELECT "order_number", "customer", "channel", "fulfilling_warehouse", "value", "placed_date", "state"
                                        FROM "order"
                                        WHERE "state" IN ('held', 'placed')) AS "t33"
                                    INNER JOIN "invoice" AS "invoice0" ON "t33"."customer" = "invoice0"."customer") AS "t34"
                        WHERE "t34"."status" = 'open' AND "t34"."due" < :as_of
                        GROUP BY "order_number") AS "t37" ON "t31"."order_number" = "t37"."order_number") AS "t38"
        WHERE "t38"."n_due" > 0
        GROUP BY "order_number") AS "t41" ON "t3"."order_number" = "t41"."order_number"
